css:
@page {
    margin: 0mm;
    size: A4;
}
body.print-format {
    background: white;
    color: #000;
}

/* ========== CONTENEDOR PRINCIPAL ========== */
.print-format-container {
    margin: 0;
    max-width: 100%;
}


html, body {
    margin: 0 !important;
    padding: 0 !important;
    width: 210mm !important;
    height: 297mm !important;
}

.print-format-builder, .print-format {
    margin: 0 !important;
    padding: 0 !important;
}

.page {
    position: relative;
    width: 210mm;
    min-height: 297mm;
    padding: 30px 40px 60px 40px;
    border-left: 18px solid #1f3b6d;
    box-sizing: border-box;
    background-color: white;

    page-break-after: always;
}

.page-fixed {
    height: 297mm;
    overflow: hidden;
}

.page-flow {
    min-height: 297mm;
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #2b2f33;
}


.header {
  display: table;
  width: 100%;
  font-size: 11px;
  letter-spacing: 1.5px;
  color: #6b7280;
  text-transform: uppercase;
  margin-bottom: 36px;
}

.header-left {
  display: table-cell;
  text-align: left;
  vertical-align: top;
}

.header-right {
  display: table-cell;
  text-align: right;
  vertical-align: top;
  font-size: 11px;
  color: #6b7280;
  text-transform: none;
  letter-spacing: 0;
}

.divider-blue {
  width: 52px;
  height: 4px;
  background: #1f3b6d;
  margin-bottom: 16px;
}

.section-label {
  color: #1f3b6d;
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.main-title {
  font-size: 38px;
  font-weight: bold;
  line-height: 1.2;
  color: #111827;
  margin-bottom: 16px;
}

.divider-orange {
  width: 52px;
  height: 4px;
  background: #f97316;
  margin-bottom: 28px;
}

.label {
  font-size: 10px;
  color: #6b7280;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-bottom: 3px;
  margin-top: 18px;
  display: block;
  border: none;
  background: none;
  padding: 0;
  text-align: left;
}

.value {
  font-size: 18px;
  font-weight: bold;
  color: #111827;
  display: block;
  border: none;
  background: none;
  padding: 0;
}

.push-down {
  height: 100mm;
}
.cover-bottom {
  position: absolute;
  bottom: 50px;
  left: 40px;
  right: 40px;
}

.stats {
  display: table;
  width: 100%;
  margin-bottom: 16px;
  margin-left: 5px;
}

.stat-item {
  display: table-cell;
  text-align: left;
  vertical-align: top;
  padding-right: 10px;
}

.stat-label {
  font-size: 9px;
  color: #6b7280;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 4px;
  display: block;
}

.stat-value {
  font-size: 20px;
  font-weight: bold;
  display: block;
}

.green  { color: #16a34a; }
.blue   { color: #1d4ed8; }
.orange { color: #f97316; }

.note {
  background: #f3f4f6;
  padding: 12px 14px;
  border-radius: 6px;
  font-size: 10px;
  color: #6b7280;
  margin-bottom: 16px;
}
.page-fixed .footer {
  position: absolute;
  bottom: 20px;
  left: 40px;
  right: 40px;

  display: table;
  width: calc(100% - 80px);

  font-size: 10px;
  color: #9ca3af;
  border-top: 0.5px solid #e5e7eb;
  padding-top: 8px;
}
.page-flow .footer {
  position: relative;
  margin-top: 30px;

  display: table;
  width: 100%;

  font-size: 10px;
  color: #9ca3af;
  border-top: 0.5px solid #e5e7eb;
  padding-top: 8px;
}
.footer-left   { display: table-cell; text-align: left; }
.footer-center { display: table-cell; text-align: center; }
.footer-right  { display: table-cell; text-align: right; }
/* Estilos para la Página 2 - Resumen Ejecutivo */
.page-number-box {
    background: #1f3b6d;
    color: white;
    width: 28px;
    height: 28px;
    display: inline-block;
    text-align: center;
    line-height: 28px;
    font-weight: bold;
    margin-right: 10px;
    vertical-align: middle;
}

.section-header {
    margin-bottom: 25px;
}

.section-title-text {
    display: inline-block;
    vertical-align: middle;
}

.section-title-text h2 {
    font-size: 18px;
    text-transform: uppercase;
    color: #111827;
}

.section-title-text p {
    font-size: 11px;
    color: #6b7280;
}

/* Layout de Tabla y Gauge */
.executive-summary-grid {
    display: table;
    width: 100%;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    margin-bottom: 20px;
}

.gauge-container {
    display: table-cell;
    width: 35%;
    vertical-align: middle;
    text-align: center;
    padding: 20px;
    border-right: 1px solid #e5e7eb;
}

.table-container {
    display: table-cell;
    width: 65%;
    padding: 15px;
    vertical-align: top;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}

.data-table th {
    text-align: left;
    color: #6b7280;
    text-transform: uppercase;
    padding-bottom: 8px;
    border-bottom: 1px solid #f3f4f6;
}

.data-table td {
    padding: 6px 0;
    border-bottom: 1px solid #f3f4f6;
}

.score-bold { font-weight: bold; color: #111827; }
.score-green { color: #16a34a; font-weight: bold; }

/* Cajas de participación (Lideres, Pares, etc) */
.participation-row {
    display: table;
    width: 100%;
    margin-bottom: 25px;
    border-spacing: 10px 0;
}

.participation-card {
    display: table-cell;
    width: 25%;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    text-align: center;
    padding: 10px;
}

.participation-label { font-size: 8px; color: #6b7280; text-transform: uppercase; }
.participation-value { font-size: 14px; font-weight: bold; display: block; }
.participation-percent { font-size: 9px; color: #16a34a; }

/* Contenedor del Gráfico Radar */
.chart-box {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 20px;
}

.chart-title {
    text-align: left;
    font-size: 12px;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 10px;
}


.chart-container {
    height: 240px; 
    text-align: center;
    overflow: hidden;
}

.chart-img {
    max-width: 100%;
    max-height: 220px; 
    width: auto;
    height: auto;
    display: inline-block;
}
/* Colores de las barras */
.bar-auto { background-color: #1f3b6d; }
.bar-lider { background-color: #7c3aed; }
.bar-pares { background-color: #10b981; }
.bar-colab { background-color: #ef4444; }
.bar-otros { background-color: #f59e0b; }

.attribute-card {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 15px;
    margin-bottom: 20px;
    page-break-inside: avoid; 
}

.attribute-header {
    display: flex;
    align-items: center;
    margin-bottom: 12px;
}

.attribute-title {
    font-size: 14px;
    font-weight: bold;
    color: #111827;
}

.attribute-desc {
    font-size: 10px;
    color: #9ca3af;
    margin-left: 10px;
}

.bar-row {
    display: flex;
    align-items: center;
    margin-bottom: 4px;
}

.bar-label {
    width: 60px;
    font-size: 9px;
    color: #6b7280;
}

.bar-container {
    flex-grow: 1;
    background-color: #f3f4f6;
    height: 8px;
    border-radius: 4px;
    margin: 0 10px;
    position: relative;
}

.bar-fill {
    height: 100%;
    border-radius: 4px;
}

.bar-value {
    width: 30px;
    font-size: 10px;
    font-weight: bold;
    text-align: right;
    color: #374151;
}

.legend-container {
    display: flex;
    gap: 15px;
    margin-bottom: 15px;
    font-size: 9px;
    color: #6b7280;
}

.legend-item { display: flex; align-items: center; }
.dot { width: 8px; height: 8px; border-radius: 50%; margin-right: 5px; }
.analysis-section {
    margin-bottom: 30px;
}

.analysis-header {
    display: flex;
    align-items: center;
    font-size: 12px;
    font-weight: bold;
    margin-bottom: 10px;
    text-transform: uppercase;
}

.dot-indicator {
    width: 10px;
    height: 10px;
    border-radius: 2px;
    margin-right: 8px;
}

.bg-green { background-color: #16a34a; }
.bg-orange { background-color: #f97316; }

.table-analysis {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-bottom: 20px;
}

.table-analysis th {
    text-align: left;
    color: #9ca3af;
    font-weight: normal;
    padding: 8px;
    border-bottom: 1px solid #e5e7eb;
}

.table-analysis td {
    padding: 10px 8px;
    border-bottom: 1px solid #f3f4f6;
    vertical-align: middle;
}

.rank-box {
    background: #f3f4f6;
    color: #6b7280;
    width: 20px;
    height: 20px;
    display: block;
    text-align: center;
    line-height: 20px;
    border-radius: 4px;
}

.question-text-cell { width: 55%; }
.question-dim { font-size: 8px; color: #9ca3af; display: block; }
.score-badge {
    padding: 4px 8px;
    border-radius: 4px;
    font-weight: bold;
    display: inline-block;
}

.badge-green { background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }
.badge-red { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }

.reflection-box {
    background: #f8fafc;
    border-radius: 8px;
    padding: 15px;
    font-size: 10px;
    color: #475569;
    border-left: 4px solid #cbd5e1;
}
/* Escala de colores del Mapa de Calor */
.heat-box {
    width: 38px;
    height: 24px;
    line-height: 24px;
    text-align: center;
    border-radius: 4px;
    font-size: 10px;
    font-weight: bold;
    display: inline-block;
    margin: 2px;
    vertical-align: middle;
}

/* Clases dinámicas */
.v-high { background-color: #16a34a; color: white; } /* >= 5.5 */
.high   { background-color: #86efac; color: #166534; } /* 5.0 - 5.4 */
.mid    { background-color: #fef08a; color: #854d0e; } /* 4.5 - 4.9 */
.low    { background-color: #fed7aa; color: #9a3412; } /* 4.0 - 4.4 */
.v-low  { background-color: #fecaca; color: #991b1b; } /* < 4.0 */

/* Tabla de Mapa de Calor */
.heatmap-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

.heatmap-table th {
    font-size: 9px;
    color: #6b7280;
    text-transform: uppercase;
    padding: 8px;
    text-align: center;
    border-bottom: 2px solid #e5e7eb;
}

.heatmap-table td {
    padding: 6px 4px;
    border-bottom: 1px solid #f3f4f6;
    font-size: 10px;
}

.dimension-row-header {
    background-color: #f8fafc;
    color: #1f3b6d;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 10px;
    padding: 8px !important;
    letter-spacing: 1px;
}

.legend-heatmap {
    display: flex;
    gap: 10px;
    font-size: 8px;
    margin-bottom: 15px;
    align-items: center;
}
/* Barras de Brecha */
.gap-bar-container {
    width: 100%;
    height: 14px;
    background: #f1f5f9;
    position: relative;
    border-radius: 2px;
    margin-top: 4px;
}
.gap-fill-others {
    height: 100%;
    background: #cbd5e1; 
    position: absolute;
}
.gap-fill-red {
    height: 100%;
    background: #fecaca; 
    position: absolute;
    right: 0;
    border-right: 2px solid #ef4444;
}
.gap-marker-auto {
    position: absolute;
    top: -4px;
    height: 22px;
    width: 2px;
    background: #1f3b6d;
    z-index: 10;
}

/* Etiquetas de dispersión */
.dispersion-box {
    display: table;
    width: 100%;
    margin-top: 20px;
}
.dispersion-col {
    display: table-cell;
    width: 50%;
    padding: 10px;
}
.sigma-value {
    font-weight: bold;
    float: right;
}
.text-red { color: #dc2626; }
.text-green { color: #16a34a; }
.matrix-container {
    display: table;
    width: 100%;
    border-spacing: 10px;
    margin-bottom: 20px;
}

.matrix-quadrant {
    display: table-cell;
    width: 50%;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 15px;
    vertical-align: top;
    min-height: 250px;
}

.quadrant-title {
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 10px;
    display: flex;
    align-items: center;
}

.quadrant-subtitle {
    font-size: 8px;
    color: #9ca3af;
    margin-bottom: 12px;
    display: block;
}

.item-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.item-list li {
    font-size: 9px;
    margin-bottom: 8px;
    padding-left: 12px;
    position: relative;
    color: #374151;
}

.item-list li::before {
    content: "•";
    position: absolute;
    left: 0;
    font-weight: bold;
}

/* Colores por cuadrante */
.q-fortaleza-conf { border-top: 4px solid #16a34a; }
.q-fortaleza-desc { border-top: 4px solid #1f3b6d; }
.q-oportunidad-conf { border-top: 4px solid #dc2626; }
.q-oportunidad-desc { border-top: 4px solid #f97316; }

.empty-msg {
    font-style: italic;
    color: #9ca3af;
    text-align: center;
    margin-top: 20px;
    font-size: 9px;
}
.open-questions-section {
    margin-bottom: 25px;
}

.question-title-container {
    display: flex;
    align-items: center;
    margin-bottom: 12px;
}

.question-bullet {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 10px;
}

.question-text {
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    color: #374151;
}

.answers-grid {
    display: block;
    column-count: 2; 
    column-gap: 20px;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 15px;
    background-color: #ffffff;
}

.answer-item {
    font-size: 9px;
    color: #4b5563;
    margin-bottom: 6px;
    break-inside: avoid; 
    display: flex;
}

.answer-item::before {
    content: "•";
    color: #9ca3af;
    margin-right: 8px;
    font-weight: bold;
}

/* Colores dinámicos para los bullets */
.bullet-green { background-color: #16a34a; }
.bullet-orange { background-color: #f97316; }
.bullet-blue { background-color: #1f3b6d; }
